<script setup lang="ts">
import InfiniteList from './InfiniteList.vue'
import {computed,onMounted,onBeforeUnmount,ref} from 'vue'
import '../comments-v16.css'
import {confirmAction} from '../confirm'
import {appendUnique,api,APIError,body,loadSession,session,list,date,type Row} from '../api'
import {clearLikeSessions,loadLike,setBookmarked,toggleLike,type LikeState} from '../postLike'
import {toast} from '../toast'
function receiveLike(e:Event){const state=(e as CustomEvent<LikeState>).detail;if(state.postId===props.postId){liked.value=state.liked;bookmarked.value=state.bookmarked;metrics.value.like_count=state.count;if(state.session?.authenticated===false){session.authenticated=false;session.user=null;session.csrf_token=''}if(state.error)error.value=state.error}}
onBeforeUnmount(()=>window.removeEventListener('painter:like',receiveLike))
const props=defineProps<{postId:string;revisionId?:string;receipt?:string}>()
const features=ref<Row>({comments_enabled:true,collections_enabled:true})
const comments=ref<Row[]>([]),metrics=ref<Row>({}),liked=ref(false),bookmarked=ref(false),text=ref(''),error=ref(''),loading=ref(true),commentsLoading=ref(false),busy=ref(false),next=ref<string|null>(null),more=ref(false)
const canInteract=computed(()=>!session.loading&&session.authenticated)
function report(e:unknown,interactive=false){if(e instanceof APIError&&e.status===401){session.authenticated=false;session.user=null;session.csrf_token='';clearLikeSessions();if(interactive)toast.error('登录已失效，请重新登录。',{id:'session-expired'});return}if(interactive)toast.error((e as Error).message,{id:'post-operation:'+props.postId});else error.value=(e as Error).message}
async function loadComments(append=false){const data=await api(`/posts/${props.postId}/comments${append&&next.value?'?cursor='+encodeURIComponent(next.value):''}`);comments.value=append?appendUnique(comments.value,list(data)):list(data);next.value=data.next_cursor;more.value=data.has_more}
async function moreComments(){if(busy.value||commentsLoading.value)return;commentsLoading.value=true;error.value='';try{await loadComments(true)}catch(e){report(e)}finally{commentsLoading.value=false}}
async function relation(kind:'like'|'bookmark'){if(!canInteract.value)return;if(kind==='like'){await toggleLike(props.postId);return}if(busy.value)return;busy.value=true;error.value='';const target=bookmarked;const before=target.value;target.value=!before;try{await api(`/posts/${props.postId}/${kind}`,{method:before?'DELETE':'PUT'});setBookmarked(props.postId,!before);toast.success(before?'已取消收藏':'文章已收藏',{id:'post-bookmark:'+props.postId})}catch(e){target.value=before;report(e,true)}finally{busy.value=false}}
async function refreshDiscussion(message:string){try{await loadComments();toast.success(message,{id:'post-operation:'+props.postId})}catch{error.value=message+'，但讨论列表未能更新，请重新加载。';toast.warning(error.value,{id:'post-operation:'+props.postId})}}
async function submit(){if(!canInteract.value||!features.value.comments_enabled||busy.value||loading.value||commentsLoading.value||!text.value.trim())return;busy.value=true;error.value='';try{await api(`/posts/${props.postId}/comments`,{method:'POST',idempotent:true,body:body({body:text.value})});text.value='';await refreshDiscussion('评论已发表')}catch(e){report(e,true)}finally{busy.value=false}}
async function remove(c:Row){if(!canInteract.value||busy.value||loading.value||commentsLoading.value||!await confirmAction('删除这条评论？','删除后无法恢复。','删除评论'))return;busy.value=true;error.value='';try{await api(`/comments/${c.id}`,{method:'DELETE'});await refreshDiscussion('评论已删除')}catch(e){report(e,true)}finally{busy.value=false}}
async function commentLike(c:Row){if(!canInteract.value||busy.value||loading.value||commentsLoading.value)return;busy.value=true;const before=c.liked;try{await api(`/comments/${c.id}/like`,{method:before?'DELETE':'PUT'});c.liked=!before;c.like_count=Number(c.like_count||0)+(before?-1:1)}catch(e){report(e,true)}finally{busy.value=false}}
async function initialize(){loading.value=true;error.value='';try{await Promise.all([loadSession(),api('/site').then(data=>{features.value=data}),loadComments()]);if(canInteract.value){const state=await loadLike(props.postId);liked.value=state.liked;bookmarked.value=state.bookmarked;metrics.value.like_count=state.count;}}catch(e){report(e)}finally{loading.value=false}}
onMounted(()=>{window.addEventListener('painter:like',receiveLike);void initialize()})
</script>
<template><div class="article-community"><div v-if="canInteract" class="interaction-bar"><button :aria-pressed="liked" :disabled="busy||loading" @click="relation('like')"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 21H4V10h3m0 11h10a2 2 0 0 0 2-1.7l1.5-9A2 2 0 0 0 18.5 8H14l1-5-2-1-6 8v11Z"/></svg>{{liked?'已点赞':'点赞'}} {{metrics.like_count??metrics.likes??''}}</button><button v-if="features.collections_enabled||bookmarked" :aria-pressed="bookmarked" :disabled="busy||loading" @click="relation('bookmark')"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h12v18l-6-4-6 4V3Z"/></svg>{{bookmarked?'已收藏':'收藏'}}</button></div>
<section class="comment-area discussion-surface" aria-labelledby="comments-title"><header class="discussion-heading"><h2 id="comments-title">一起聊聊</h2><span v-if="!loading&&!error" class="discussion-count">{{comments.length?`已载入 ${comments.length} 条讨论`:'等一个新想法'}}</span></header>
<div v-if="error" class="notice error" role="alert">{{error}} <button type="button" class="quiet" :disabled="busy||loading||commentsLoading" @click="initialize">重新加载讨论</button></div><p v-if="!features.comments_enabled&&canInteract" class="notice">站点目前关闭了新评论，已有讨论仍然保留。</p>
<form v-if="canInteract&&features.comments_enabled" class="discussion-composer" @submit.prevent="submit"><label for="comment-body">分享你的想法<textarea id="comment-body" v-model="text" maxlength="5000" rows="3" required placeholder="留下你的思考，让讨论继续。" :disabled="busy"></textarea></label><div><small>友善交流，言之有物。</small><button class="primary" :disabled="busy||loading||commentsLoading||!text.trim()">{{busy?'提交中…':'发表评论'}}</button></div></form>
<div v-if="loading" class="discussion-loading" role="status">正在载入讨论…</div>
<div class="discussion-list"><article v-for="c in comments" :key="c.id" class="discussion-comment"><a :href="'/users/'+c.user?.id" class="discussion-avatar" :aria-label="c.user?.display_name"><img v-if="c.user?.avatar_url" class="avatar" :src="c.user.avatar_url" width="36" height="36" alt=""><span v-else class="avatar">{{(c.user?.display_name||'?').slice(0,1)}}</span></a><div class="discussion-author"><a :href="'/users/'+c.user?.id"><strong>{{c.user?.display_name}}</strong></a><time :datetime="c.created_at">{{date(c.created_at)}}</time></div><p class="discussion-body">{{c.body}}</p><div v-if="canInteract" class="discussion-actions"><button class="quiet" :disabled="busy||loading||commentsLoading" :aria-pressed="!!c.liked" @click="commentLike(c)"><svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M7 21H4V10h3m0 11h10a2 2 0 0 0 2-1.7l1.5-9A2 2 0 0 0 18.5 8H14l1-5-2-1-6 8v11Z"/></svg>{{c.liked?'已赞':'赞'}} {{c.like_count||0}}</button><button v-if="c.is_self||session.user?.role==='owner'" class="quiet danger" :disabled="busy||loading||commentsLoading" @click="remove(c)">删除</button></div></article></div>
<p v-if="!loading&&!error&&!comments.length" class="discussion-empty">还没有评论。</p><InfiniteList :has-more="more" :loading="loading||commentsLoading" :disabled="busy" :error="error" @load="moreComments"/></section></div></template>
